function parse_nested_parens(paren_string){
  let max_depth = 0;
  let current_depth = 0;
  const groups = paren_string.split(' ');
  const results = [];

  for (const group of groups) {
    current_depth = 0;
    max_depth = 0;

    for (const char of group) {
      if (char === '(') {
        current_depth++;
        if (current_depth > max_depth) {
          max_depth = current_depth;
        }
      } else if (char === ')') {
        current_depth--;
      }
    }

    results.push(max_depth);
  }

  return results;
}

